+// RF-004: descuento opcional en porcentaje (0 a 100), aplicado a la línea y redondeado al centavo.
+function totalLineaCentavos({ cantidad, precioUnitarioCentavos, descuentoPorcentaje = 0 }) {
+  if (typeof descuentoPorcentaje !== "number" || !(descuentoPorcentaje >= 0 && descuentoPorcentaje <= 100))
+    throw new RangeError("Descuento inválido: debe ser un porcentaje entre 0 y 100");
+  return Math.round((cantidad * precioUnitarioCentavos * (100 - descuentoPorcentaje)) / 100);
+}
